//go:build windows

// ModAVD.exe: the desktop manager of one ModAVD root. It runs the local server of package ui and opens it in an Edge
// app window; closing the window ends it (after running jobs are done). Double-clicking it again while it runs only
// reopens the window.
//
//	ModAVD.exe [--root <dir>] [--port N] [--no-window] [--dev]
//
// Build (GUI subsystem: no console window):
//
//	go build -trimpath -buildvcs=false -ldflags "-H=windowsgui -s -w" -o ModAVD.exe ./cmd/modavd-gui
//
// rsrc_windows_amd64.syso next to this file carries the icon and the manifest; it is generated by ./winres (see
// there). The icon (modavd.ico) is fan art and is not covered by the code licence.
package main

//go:generate go run ./winres

import (
	"context"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"runtime/debug"
	"strings"
	"syscall"
	"time"

	"modavd/internal/emu"
	"modavd/internal/errs"
	"modavd/internal/logx"
	"modavd/internal/root"
	"modavd/internal/ui"
	"modavd/internal/win"
)

func main() {
	// Hidden subcommands first, before any flag parsing or root lookup: emu and win re-run this executable as the
	// spawn helper of win.StartOrphan, as the Vulkan probe child and as the boot watch (same routing as internal/cli
	// Main).
	if len(os.Args) > 1 {
		switch os.Args[1] {
		case win.SpawnHelperArg:
			os.Exit(win.SpawnHelperMain(os.Args[2:], os.Stdout))
		case emu.VulkanProbeArg:
			os.Exit(emu.RunVulkanProbe(os.Stdout))
		case emu.BootWatchArg:
			os.Exit(emu.RunBootWatch(os.Args[2:], os.Stderr))
		}
	}
	if exe, err := os.Executable(); err == nil {
		win.OrphanHelper = exe
	}
	os.Exit(run(os.Args[1:]))
}

const usage = "用法：ModAVD.exe [--root 根目录] [--port 端口] [--no-window] [--dev]"

func run(args []string) (code int) {
	var log *logx.Logger
	defer func() {
		// A GUI process has no console: a panic would otherwise end it without a trace.
		if p := recover(); p != nil {
			log.Errorf("管理器崩溃: %v\n%s", p, debug.Stack())
			fatal(fmt.Sprintf("管理器出错退出了：%v", p))
			code = 1
		}
	}()

	fs := flag.NewFlagSet("ModAVD", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	rootFlag := fs.String("root", "", "魔改 AVD 根目录")
	port := fs.Int("port", 0, "监听端口（0 = 随机）")
	noWindow := fs.Bool("no-window", false, "不打开窗口")
	dev := fs.Bool("dev", false, "开发模式：提供 /dev/ 的模拟后端页面，没有窗口也不自动退出")
	if err := fs.Parse(args); err != nil {
		fatal("命令行参数不对：" + err.Error() + "\n\n" + usage)
		return 2
	}
	if fs.NArg() > 0 {
		fatal("多余的参数：" + strings.Join(fs.Args(), " ") + "\n\n" + usage)
		return 2
	}
	if *port < 0 || *port > 65535 {
		fatal(fmt.Sprintf("端口 %d 不对（0–65535，0 = 随机）", *port))
		return 2
	}
	r, err := root.Resolve(*rootFlag)
	if err != nil {
		fatalErr("找不到魔改 AVD 根目录", err)
		return errs.ExitCode(err)
	}

	minLevel := logx.Info
	if *dev {
		minLevel = logx.Debug
	}
	// Not closed by a defer: the crash handler above still writes to it, and the process exit closes it anyway.
	logFile := openLogFile(r.LogsDir())
	log = logx.New(logFile.sink(minLevel))

	inst, err := lockInstance(r)
	if err != nil {
		log.Errorf("%v", err)
		fatalErr("管理器启动失败", err)
		return 1
	}
	if inst == nil {
		return reopen(r, *noWindow, log)
	}
	defer inst.release()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	opt := ui.Options{
		Root:       r,
		Log:        log,
		Addr:       fmt.Sprintf("127.0.0.1:%d", *port),
		OpenWindow: !*noWindow,
		Dev:        *dev,
		Ready: func(baseURL, token string) {
			if err := inst.writeState(baseURL, token); err != nil {
				log.Warnf("写不了管理器状态文件（再次打开时找不到这个管理器）: %v", err)
			}
		},
	}
	if *dev {
		opt.IdleExit = -1
	}
	if err := ui.Run(ctx, opt); err != nil {
		log.Errorf("%v", err)
		// let go of the root first: the message box stays up until it is clicked away, and a new launch meanwhile
		// must not take this dead manager for a running one
		inst.release()
		fatalErr("管理器启动失败", err)
		return errs.ExitCode(err)
	}
	return 0
}

// reopen is the second launch on a root: the running manager gets a new window.
func reopen(r *root.Root, noWindow bool, log *logx.Logger) int {
	st, err := readStateWait(r, 5*time.Second)
	if err != nil {
		log.Errorf("已有管理器在运行，但读不到它的地址: %v", err)
		fatal("这个根目录的 ModAVD 管理器已经在运行，但找不到它的地址。\n\n" +
			"请关掉已经打开的管理器窗口，等十几秒后再打开；还不行就在任务管理器里结束 ModAVD.exe。\n\n根目录：" + r.Dir)
		return 1
	}
	if noWindow {
		return 0
	}
	log.Infof("管理器已在运行（%s），重新打开窗口", st.URL)
	if _, err := ui.LaunchWindow(st.URL + "?t=" + st.Token); err != nil {
		log.Errorf("打不开管理器窗口: %v", err)
		fatal("打不开管理器窗口：" + err.Error() + "\n\n可以在浏览器里打开 " + st.URL)
		return 1
	}
	return 0
}

func fatalErr(what string, err error) {
	e := errs.As(err)
	msg := what + "：\n\n" + e.Message
	if e.Advice != "" {
		msg += "\n\n" + e.Advice
	}
	fatal(msg)
}
